// ── State & event wiring ─────────────────────────────────────────────────────
function openModal() {
  const overlay = document.getElementById('delete-modal');
  overlay.classList.add('is-open');
  overlay.removeAttribute('aria-hidden');

  // Return focus to trigger on close; store reference
  overlay._returnFocus = document.getElementById('delete-trigger');

  // Move focus into dialog
  const firstFocusable = overlay.querySelector(
    'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
  );
  if (firstFocusable) firstFocusable.focus();

  // Trap focus inside dialog
  overlay.addEventListener('keydown', trapFocus);
  document.addEventListener('keydown', handleEsc);
}

function closeModal() {
  const overlay = document.getElementById('delete-modal');
  overlay.classList.remove('is-open');
  overlay.setAttribute('aria-hidden', 'true');
  overlay.removeEventListener('keydown', trapFocus);
  document.removeEventListener('keydown', handleEsc);

  if (overlay._returnFocus) {
    overlay._returnFocus.focus();
  }
}

function confirmDelete() {
  closeModal();
  // In a real app: call API to delete the image
  const card = document.querySelector('.preview-card');
  if (card) {
    card.style.transition = 'opacity 300ms ease, transform 300ms ease';
    card.style.opacity = '0';
    card.style.transform = 'scale(0.97)';
    setTimeout(() => {
      card.innerHTML = `
        <div style="padding: 60px 28px; text-align: center; color: var(--text-secondary);">
          <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" style="margin: 0 auto 16px; display:block; opacity:0.4" aria-hidden="true">
