+          <p style="font-size:0.875rem">The image has been removed from your library.</p>
+        </div>
+      `;
+      card.style.opacity = '1';
+      card.style.transform = 'scale(1)';
+    }, 320);
+  }
+}
+
+function handleEsc(e) {
+  if (e.key === 'Escape') closeModal();
+}
+
+function trapFocus(e) {
+  if (e.key !== 'Tab') return;
+  const dialog = document.querySelector('.modal-dialog');
+  const focusable = Array.from(
+    dialog.querySelectorAll(
+      'button:not([disabled]), [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
+    )
+  );
+  const first = focusable[0];
+  const last = focusable[focusable.length - 1];
+
+  if (e.shiftKey) {
+    if (document.activeElement === first) {
+      e.preventDefault();
+      last.focus();
+    }
+  } else {
+    if (document.activeElement === last) {
+      e.preventDefault();
+      first.focus();
+    }
+  }
+}
+
+// ── Bootstrap ────────────────────────────────────────────────────────────────
+document.addEventListener('DOMContentLoaded', () => {
+  document.getElementById('app').innerHTML = App();
+
+  // Event delegation for all interactive elements
+  document.addEventListener('click', (e) => {
+    // Open dialog via trigger button
+    if (e.target.closest('.trigger')) {
+      openModal();
+      return;
+    }
+
+    // Close / confirm actions inside modal
+    const action = e.target.closest('[data-action]')?.dataset.action;
+    if (action === 'close') closeModal();
+    if (action === 'confirm') confirmDelete();
+
+    // Click outside dialog to close
+    if (e.target.classList.contains('modal-overlay') && e.target.classList.contains('is-open')) {
+      closeModal();
+    }
+  });
